def _save_lessons(self):
        import tempfile
        target_path = self._lessons_file
        target_dir = os.path.dirname(os.path.abspath(target_path))
        tmp_path = None
        try:
            os.makedirs(target_dir, exist_ok=True)
            fd, tmp_path = tempfile.mkstemp(dir=target_dir, prefix='.lessons-', suffix='.tmp')
            try:
                with os.fdopen(fd, 'w', encoding='utf-8') as f:
                    json.dump(self._lessons, f, ensure_ascii=False, indent=2)
                    f.flush()
                    os.fsync(f.fileno())
                os.replace(tmp_path, target_path)
                tmp_path = None
            finally:
                if tmp_path is not None:
                    try:
                        os.unlink(tmp_path)
                    except OSError:
                        pass
        except Exception as e:
            self._log(LogLevel.WARNING, f"学习库保存失败: {e}")

def _schedule_exploration(self):
        if not self._running:
            return
        if self._next_timer:
            self._next_timer.cancel()
        _actual_interval = self._current_interval
        try:
            _tempo = self._get_background_tempo()
            _actual_interval = max(self._min_interval, self._current_interval * _tempo)
        except Exception as e:
            self._log(LogLevel.WARNING, f"exception ignored (needs attention): {type(e).__name__}: {e}")
        self._next_timer = threading.Timer(
            _actual_interval,
            self._trigger_exploration
        )
        self._next_timer.daemon = True
        self._next_timer.start()

def _get_background_tempo(self):
        _bus = getattr(self, "_pulse_bus", None)
        if _bus is None:
            _bus = getattr(self, "_bus", None)
        if _bus is not None:
            for _method_name in ("get_background_tempo", "request_background_tempo"):
                _getter = getattr(_bus, _method_name, None)
                if callable(_getter):
                    return _getter()
        _provider = getattr(self, "_tempo_provider", None)
        if callable(_provider):
            return _provider()
        return get_runtime_tempo().get_background_tempo()

def _on_dream_timer(self):
        try:
            if not self._running or self._user_present:
                return
            # FIX(重入保护): 上一轮梦境未完成时跳过本轮, 避免重叠执行
            if getattr(self, '_dream_in_progress', False):
                # FIX(cross_module_singleton_call): 不再直接 import 并调用
                # nucleus.runtime_metrics 单例, 改为通过脉冲总线发布埋点事件,
                # 由订阅方自行上报, 避免跨模块隐式耦合
                try:
                    publisher = getattr(self, '_publish_pulse', None)
                    if publisher is None:
                        publisher = getattr(self, '_emit_pulse', None)
                    if publisher is not None:
                        publisher(
                            "runtime_metric",
                            {
                                "name": "reentry",
                                "key": "dream",
                                "source": "dream_scheduler",
                            },
                        )
                except Exception as e:
                    self._log(LogLevel.WARNING, f"异常已忽略（需关注）: {type(e).__name__}: {e}")
                return
            if self._is_system_busy():
                return

            # 立即更新时间, 然后执行
            self._dream_next_time = time.time() + self._dream_interval
            self._trigger_dream()
        finally:
            # P2-8/AP53 修复: 无论任何分支(早退/异常)都续期梦境定时器,
            # 避免 _trigger_dream 抛异常导致定时器永久停摆
            self._schedule_dream_timer()

