def _count_nodes(self) -> int:
        # fix: remove cross-module singleton call (from nucleus.knowledge_access_layer import get_kal)
        # now the KAL node count is requested through the pulse bus, so the module
        # no longer reaches into another module's singleton directly
        _bus = getattr(self, "pulse_bus", None) or getattr(self, "bus", None)
        _sender = None
        if _bus is not None:
            _sender = getattr(_bus, "request", None) or getattr(_bus, "query", None)
        if _sender is not None:
            for _topic in ("kal.node_count", "knowledge.node_count"):
                try:
                    _resp = _sender(_topic, {})
                    if isinstance(_resp, dict):
                        _resp = _resp.get("count") or _resp.get("node_count") or _resp.get("value")
                    if _resp:
                        return int(_resp)
                except Exception as e:
                    self._log(LogLevel.WARNING, f"[肝] 脉冲总线节点统计异常: {type(e).__name__}: {e}")
        # fallback: local node pool statistics, no implicit coupling to other modules
        try:
            _pool = getattr(self, "node_pool", None)
            if _pool is not None:
                return len(getattr(_pool, "_hot", {}) or {}) + \
                    len(getattr(_pool, "_warm", {}) or {}) + \
                    len(getattr(_pool, "_cold", {}) or {})
        except Exception as e:
            self._log(LogLevel.WARNING, f"[肝] 节点池统计异常: {type(e).__name__}: {e}")
        return 0

